CREATE TABLE "public"."lgpd_consentimentos" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cliente_id"    bigint                   NOT NULL,
  "finalidade"    text                     NOT NULL,
  "versao_termo"  text                     NOT NULL,
  "consentiu"     boolean                  NOT NULL,
  "registrado_em" timestamp with time zone NOT NULL DEFAULT now(),
  "origem"        text                     NOT NULL DEFAULT 'aplicativo'::text,
  CONSTRAINT "ck_lgpd_finalidade" CHECK ((length(TRIM(BOTH FROM finalidade)) > 0)),
  CONSTRAINT "ck_lgpd_origem" CHECK ((origem = ANY (ARRAY['aplicativo'::text, 'web'::text, 'atendimento'::text, 'administrativo'::text]))),
  CONSTRAINT "ck_lgpd_versao" CHECK ((length(TRIM(BOTH FROM versao_termo)) > 0)),
  CONSTRAINT "lgpd_consentimentos_cliente_id_fkey" FOREIGN KEY (cliente_id) REFERENCES public.clientes(id) ON DELETE CASCADE,
  CONSTRAINT "lgpd_consentimentos_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."lgpd_consentimentos"
  ENABLE ROW LEVEL SECURITY;

CREATE INDEX ix_lgpd_cliente_data ON public.lgpd_consentimentos USING btree (cliente_id, registrado_em DESC);

CREATE POLICY "cliente_le_proprios_consentimentos" ON "public"."lgpd_consentimentos"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.clientes c
  WHERE ((c.id = lgpd_consentimentos.cliente_id) AND (c.auth_user_id = auth.uid())))));

REVOKE ALL ON SEQUENCE "public"."lgpd_consentimentos_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."lgpd_consentimentos_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."lgpd_consentimentos_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."lgpd_consentimentos_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."lgpd_consentimentos_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."lgpd_consentimentos_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."lgpd_consentimentos_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."lgpd_consentimentos_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."lgpd_consentimentos" TO "service_role";

COMMENT ON TABLE "public"."lgpd_consentimentos" IS 'Histórico de consentimento por cliente, finalidade e versão do termo.';

REVOKE ALL ON TABLE "public"."lgpd_consentimentos" FROM "authenticated";

GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON TABLE "public"."lgpd_consentimentos" TO "authenticated";

REVOKE ALL ON TABLE "public"."lgpd_consentimentos" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."lgpd_consentimentos" TO "postgres";

REVOKE ALL ON TABLE "public"."lgpd_consentimentos" FROM "anon";
